class Solution:
    def isValidSudoku(self, board: list[list[str]]) -> bool:
        seen: set[str] = set()
        for r, row in enumerate(board):
            for c, d in enumerate(row):
                if d == ".":
                    continue
                keys = (f"{d} in row {r}", f"{d} in col {c}", f"{d} in box {r // 3}-{c // 3}")  # viz:keys
                for key in keys:
                    if key in seen:  # viz:check
                        return False  # viz:clash
                    seen.add(key)
        return True  # viz:done
